'use strict';
(() => {
  const root = document.getElementById('profile-view');
  if (!root) return;
  const esc = value => String(value ?? '');
  const date = value => value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' }).format(new Date(value)) : 'Waiting to sync';
  const cardFor = key => {
    const [lessonId, indexText] = String(key).split(':');
    const lesson = LESSONS.find(item => item.id === lessonId), index = Number(indexText);
    return lesson && lesson.cards[index] ? { lesson, card: lesson.cards[index], index } : null;
  };
  root.innerHTML = `<div class="profile-guest panel"><h2>Your learning, in one place.</h2><p>Sign in to see your saved cards, lesson progress and history on any device.</p><p lang="my">အကောင့်ဝင်ပြီး သိမ်းထားတဲ့ကတ်တွေ၊ သင်ခန်းစာတိုးတက်မှုနဲ့ မှတ်တမ်းတွေကို ကြည့်ပါ။</p><button id="profile-login" class="primary">Sign in / ဝင်မယ်</button></div>
  <div class="profile-content" hidden><div class="profile-heading"><div class="profile-avatar" id="profile-avatar">◎</div><div><h2 id="profile-greeting">Your learning journey</h2><p>Small steps, saved for you. <span lang="my">လေ့ကျင့်မှုတိုင်းကို မှတ်တမ်းတင်ပါ။</span></p></div></div>
  <p id="profile-load-status" class="profile-notice" role="status"></p><div class="profile-stats"><div><strong id="profile-total">0</strong><span>Cards saved<small lang="my">သိမ်းထားသော ကတ်များ</small></span></div><div><strong id="profile-lessons">0</strong><span>Lessons completed<small lang="my">ပြီးဆုံးသော သင်ခန်းစာများ</small></span></div><div><strong id="profile-pending">0</strong><span>Waiting to sync<small lang="my">သိမ်းဆည်းရန် စောင့်နေသည်</small></span></div></div>
  <div class="profile-tabs" role="tablist"><button class="secondary" data-profile-tab="overview" aria-selected="true">Progress / တိုးတက်မှု</button><button class="secondary" data-profile-tab="history" aria-selected="false">History / မှတ်တမ်း</button><button class="secondary" data-profile-tab="settings" aria-selected="false">Settings / ဆက်တင်များ</button></div>
  <section data-profile-panel="overview"><div class="profile-section-heading"><h2>Lesson progress</h2><label>Show / ပြမယ်<select id="progress-filter"><option value="started">Started lessons</option><option value="all">All lessons</option><option value="complete">Completed lessons</option></select></label></div><div id="profile-lesson-list" class="profile-lesson-grid"></div></section>
  <section data-profile-panel="history" hidden><div class="panel"><h2>Your saved-card history</h2><p>Each card appears once, with the date it was first saved to your account. Repeating a card keeps its original date. Offline practice receives a date when it syncs.</p><p lang="my">ကတ်တစ်ခုစီကို အကောင့်မှာ ပထမဆုံး သိမ်းတဲ့ရက်နဲ့ တစ်ကြိမ်ပဲ ပြပါမယ်။ ထပ်လေ့ကျင့်ရင် မူလရက်ကို ထိန်းထားပါမယ်။</p><label class="history-filter">Lesson / သင်ခန်းစာ<select id="history-filter"><option value="all">All lessons</option></select></label><ol id="profile-history-list" class="history-list"></ol><p id="history-empty" class="empty-note" hidden>No saved cards yet. Complete a listening answer or tap “I practised this” in speaking practice.<br><span lang="my">မှတ်တမ်း မရှိသေးပါ။</span></p></div></section>
  <section data-profile-panel="settings" hidden><div class="settings-grid"><div class="panel"><h2>Account profile / အကောင့်</h2><form id="profile-form"><label for="profile-name">Display name / အမည်</label><input id="profile-name" maxlength="80" autocomplete="nickname" placeholder="Your name"><p class="field-note">Your name appears only in your profile.</p><label for="profile-email">Email / အီးမေးလ်</label><input id="profile-email" type="email" readonly><button id="profile-save" type="submit" class="primary">Save profile / သိမ်းမယ်</button></form><div class="profile-theme-control"><p>Theme / အရောင်</p><button id="profile-theme" class="secondary theme-toggle" type="button" data-theme-toggle aria-label="Switch to dark mode / အမှောင်သို့ ပြောင်းမယ်">☾ Dark mode / အမှောင်</button></div></div><div><div class="panel"><h2>Account settings</h2><p>Send a password-reset link to your account email.</p><button id="profile-reset" class="secondary">Send password reset email</button><button id="profile-signout" class="text-button">Sign out on this device / ထွက်မယ်</button></div><div class="panel" id="guest-import-panel" hidden><h2>Earlier guest practice</h2><p id="guest-import-description"></p><p>Only add it if this practice is yours. It will become part of this account’s private progress.</p><button id="profile-import" class="secondary">Add guest practice to my account</button></div></div></div><p id="profile-settings-status" class="profile-notice" role="status"></p></section></div>`;
  const q = selector => root.querySelector(selector), all = selector => [...root.querySelectorAll(selector)];
  function setStatus(text, error = false) { const node = q('#profile-settings-status'); if (window.NihongoI18n) window.NihongoI18n.setText(node, text); else node.textContent = text; node.classList.toggle('error', error); }
  function render(snapshot = window.NihongoAccount?.getSnapshot?.()) {
    if (!snapshot?.signedIn) { q('.profile-guest').hidden = false; q('.profile-content').hidden = true; return; }
    q('.profile-guest').hidden = true; q('.profile-content').hidden = false;
    const name = snapshot.user.displayName || snapshot.user.email.split('@')[0] || 'Learner';
    q('#profile-greeting').textContent = `${name}'s learning journey`; q('#profile-avatar').textContent = name.slice(0, 1).toUpperCase(); q('#profile-email').value = snapshot.user.email; q('#profile-name').value = snapshot.user.displayName;
    q('#profile-total').textContent = snapshot.records.length; q('#profile-pending').textContent = snapshot.pendingCount;
    q('#profile-load-status').textContent = snapshot.loadState === 'cached' ? 'Showing your last saved copy while cloud sync is unavailable.' : snapshot.loadState === 'error' ? 'Progress could not be refreshed. Try Retry sync.' : snapshot.pendingCount ? 'Some new practice is waiting to sync.' : 'Your account progress is up to date.';
    const counts = new Map(); snapshot.records.forEach(row => { const info = cardFor(row.key); if (info) counts.set(info.lesson.id, (counts.get(info.lesson.id) || 0) + 1); });
    q('#profile-lessons').textContent = [...counts].filter(([id, count]) => count >= (LESSONS.find(l => l.id === id)?.cards.length || 15)).length;
    const filter = q('#progress-filter').value; const list = q('#profile-lesson-list'); list.replaceChildren();
    for (const lesson of LESSONS) { const count = counts.get(lesson.id) || 0, complete = count >= lesson.cards.length; if ((filter === 'started' && !count) || (filter === 'complete' && !complete)) continue; const item = document.createElement('article'); item.className = 'profile-lesson-card'; const title = document.createElement('h3'); title.textContent = lesson.name; const meter = document.createElement('div'); meter.className = 'profile-meter'; const fill = document.createElement('span'); fill.style.width = `${Math.min(100, Math.round(count / lesson.cards.length * 100))}%`; meter.append(fill); const text = document.createElement('p'); text.textContent = `${count} / ${lesson.cards.length} cards saved`; const button = document.createElement('button'); button.className = 'secondary'; button.textContent = count ? 'Continue lesson' : 'Start lesson'; button.onclick = () => window.NihongoPractice?.openLesson(lesson.id, [...snapshot.records].map(r => r.key).find(k => k.startsWith(`${lesson.id}:`))); item.append(title, meter, text, button); list.append(item); }
    renderHistory(snapshot); renderGuestImport(snapshot); window.NihongoTheme?.refreshButtons();
  }
  function renderHistory(snapshot) { const select = q('#history-filter'), previous = select.value; select.replaceChildren(); const allOption = document.createElement('option'); allOption.value = 'all'; allOption.textContent = 'All lessons'; select.append(allOption); LESSONS.forEach(l => { const o = document.createElement('option'); o.value = l.id; o.textContent = l.name; select.append(o); }); select.value = [...select.options].some(o => o.value === previous) ? previous : 'all'; const list = q('#profile-history-list'); list.replaceChildren(); const rows = snapshot.records.filter(row => select.value === 'all' || row.key.startsWith(`${select.value}:`)).sort((a, b) => (b.completedAt || '').localeCompare(a.completedAt || '')); q('#history-empty').hidden = rows.length > 0; for (const row of rows) { const info = cardFor(row.key); if (!info) continue; const li = document.createElement('li'), top = document.createElement('div'), jp = document.createElement('strong'), detail = document.createElement('span'), action = document.createElement('button'); jp.lang = 'ja'; jp.textContent = info.card.jp; detail.textContent = `${info.lesson.name} · ${row.pending ? 'Waiting to sync' : `First saved ${date(row.completedAt)}`}`; action.className = 'text-button'; action.textContent = 'Practise again'; action.onclick = () => window.NihongoPractice?.openLesson(info.lesson.id, row.key); top.append(jp, detail); li.append(top, action); list.append(li); } }
  function renderGuestImport(snapshot) { const count = window.NihongoAccount?.getGuestCount?.() || 0; q('#guest-import-panel').hidden = !count; if (count) q('#guest-import-description').textContent = `${count} card${count === 1 ? '' : 's'} were practised on this device before sign-in.`; }
  q('#profile-login').onclick = () => { document.getElementById('account-button').click(); };
  q('#progress-filter').onchange = () => render(); q('#history-filter').onchange = () => renderHistory(window.NihongoAccount.getSnapshot());
  all('[data-profile-tab]').forEach(button => button.onclick = () => { const tab = button.dataset.profileTab; all('[data-profile-tab]').forEach(b => b.setAttribute('aria-selected', b === button)); all('[data-profile-panel]').forEach(panel => { panel.hidden = panel.dataset.profilePanel !== tab; }); });
  q('#profile-form').onsubmit = async event => { event.preventDefault(); q('#profile-save').disabled = true; setStatus('Saving profile…'); try { await window.NihongoAccount.saveProfile(q('#profile-name').value); setStatus('Profile saved. / အကောင့်အချက်အလက် သိမ်းပြီးပါပြီ'); render(); } catch (error) { setStatus(error.message || 'Could not save profile.', true); } finally { q('#profile-save').disabled = false; } };
  q('#profile-reset').onclick = async () => { q('#profile-reset').disabled = true; setStatus('Sending reset email…'); try { await window.NihongoAccount.requestPasswordReset(); setStatus('If your account can receive mail, check your inbox for the reset link.'); } catch (error) { setStatus(error.message || 'Could not send reset email.', true); } finally { q('#profile-reset').disabled = false; } };
  q('#profile-signout').onclick = async () => { try { await window.NihongoAccount.signOut(); window.NihongoPractice?.navigate('practice'); } catch (error) { setStatus(error.message || 'Could not sign out.', true); } };
  q('#profile-import').onclick = async () => { q('#profile-import').disabled = true; try { const count = await window.NihongoAccount.importGuestProgress(); setStatus(`${count} guest card${count === 1 ? '' : 's'} added to your account.`); render(); } catch (error) { setStatus(error.message || 'Could not import guest practice.', true); } finally { q('#profile-import').disabled = false; } };
  window.addEventListener('progresschange', event => render(event.detail.snapshot)); window.addEventListener('identitychange', () => render());
  window.NihongoTheme?.refreshButtons();
  render();
})();
